import { useState, useEffect } from 'react';
import { ref, get } from 'firebase/database';
import { database } from '../firebase';
import { useAuth } from '../AuthContext';

const useAdmin = () => {
  const [isAdmin, setIsAdmin] = useState(false);
  const { currentUser } = useAuth();

  useEffect(() => {
    const checkAdminStatus = async () => {
      console.log("=== useAdmin Hook Debug ===");
      console.log("Current user in useAdmin:", currentUser);
      console.log("User UID in useAdmin:", currentUser?.uid);
      
      if (currentUser) {
        const adminRef = ref(database, `admins/${currentUser.uid}`);
        console.log("Checking admin path:", `admins/${currentUser.uid}`);
        
        try {
          const snapshot = await get(adminRef);
          console.log("Admin snapshot exists:", snapshot.exists());
          console.log("Admin snapshot value:", snapshot.val());
          setIsAdmin(snapshot.exists());
        } catch (error) {
          console.error("Error checking admin status:", error);
          setIsAdmin(false);
        }
      } else {
        console.log("No current user, setting isAdmin to false");
        setIsAdmin(false);
      }
      console.log("Final isAdmin state:", isAdmin);
      console.log("=========================");
    };

    checkAdminStatus();
  }, [currentUser]);

  return isAdmin;
};

export default useAdmin;
